def source_file(name):
    home = Path(__file__).parent
    if name in LOCAL_IMPLEMENTATIONS:
        return home / LOCAL_IMPLEMENTATIONS[name]
    if name in LITERATURE_BINDING_SOURCES:
        return home / name
    if Path(name).name != name:
        raise ValueError('literature_implementation_basename_required')
    path = home.parents[4] / name
    if not path.is_file():
        path = home.parents[4] / 'library' / name
    if not path.is_file():
        raise FileNotFoundError(name)
    return path
